/** The command the person typed (`crewboard` or its short alias `orch`): usage lines and hints repeat it. */
let program = 'crewboard'
export const setProgram = (name: string): void => { program = name }
export const programName = (): string => program
/** `orch` when started through that alias, otherwise the product's command (a Windows shim runs main.js). */
export const programOf = (script: string | undefined): string => (/^orch(?:\.\w+)?$/.test(script?.split(/[\\/]/).at(-1) ?? '') ? 'orch' : 'crewboard')

/**
 * The Russian texts are a file of their own (dist/dict-ru.js, ~60 KiB): every call parses main.js, and an English
 * one never needs them. `run` loads the language it speaks before it prints anything.
 */
let ru: Record<string, string> | undefined
export async function loadLang(lang: Lang): Promise<void> {
  if (lang === 'ru' && !ru) ru = (await import('./dict-ru.js')).ru
}

// CLI-local dictionary follows the client t(key, vars) API without importing its browser bundle.
export function cliT(lang: Lang, key: string, vars: Record<string, string | number> = {}): string {
  const all: Record<string, string | number> = { prog: program, ...vars }
  if (lang === 'ru' && !ru) throw new Error('The Russian CLI texts are not loaded: await loadLang(\'ru\') first')
  return (lang === 'ru' ? ru?.[key] ?? en[key] : en[key])?.replace(/\{([\w]+)\}/g, (m, n: string) => all[n] === undefined ? m : String(all[n])) ?? key
}
export function envLang(env: NodeJS.ProcessEnv): Lang { const locale = env.LC_ALL || env.LANG || ''; return /^ru(?:[_\-.]|$)/i.test(locale) ? 'ru' : 'en' }

/** A count-dependent text, picked by `Intl.PluralRules` off `{keyBase}.<category>`; falls back to `{keyBase}.other` when a language has no entry for the selected category. */
export function pluralT(lang: Lang, keyBase: string, count: number): string {
  const key = `${keyBase}.${new Intl.PluralRules(lang).select(count)}`
  const text = cliT(lang, key, { count })
  return text === key ? cliT(lang, `${keyBase}.other`, { count }) : text
}
